<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>Educational Tour Manifest</title><style>
@page{size:A4;margin:12mm 14mm}*{box-sizing:border-box}body{font-family:DejaVu Sans,sans-serif;color:#142033;font-size:9px;margin:0}.header,.meta,.fleet,.signatures{width:100%;border-collapse:collapse}.header{border-bottom:3px solid #123c69;padding-bottom:8px}.brand{font-size:15px;font-weight:bold;color:#123c69}.title{text-align:right;font-size:15px;font-weight:bold;letter-spacing:1px}.meta{margin:12px 0;background:#f1f6fb}.meta td{padding:7px 8px;border:1px solid #dbe5ef;vertical-align:top}.label{display:block;font-size:7px;font-weight:bold;text-transform:uppercase;letter-spacing:.5px;color:#607087;margin-bottom:2px}.fleet th{background:#123c69;color:#fff;padding:7px 5px;text-align:left;font-size:8px;text-transform:uppercase}.fleet td{padding:7px 5px;border-bottom:1px solid #dbe5ef}.section{font-size:9px;font-weight:bold;color:#123c69;text-transform:uppercase;letter-spacing:.6px;border-bottom:1px solid #b9c8d8;padding-bottom:4px;margin:14px 0 6px}.signatures{margin-top:30px}.signatures td{width:33%;padding:0 12px;text-align:center}.line{border-top:1px solid #39495d;padding-top:4px}.footer{margin-top:14px;border-top:1px solid #c5d1de;padding-top:7px;color:#607087;font-size:7px}</style></head><body>
<table class="header"><tr><td><div class="brand">{{ $company['name'] }}</div><div>{{ $company['address'] }}</div></td><td class="title">EDUCATIONAL TOUR<br>MASTER MANIFEST<br><span style="font-size:8px;color:#607087">{{ $booking->reference }}</span></td></tr></table>
<table class="meta"><tr><td><span class="label">School / group</span><strong>{{ $booking->school_name }}</strong><br>{{ $booking->grade_level }}</td><td><span class="label">Contact person</span>{{ $booking->contact_person }}<br>{{ $booking->contact_number }} | {{ $booking->contact_email }}</td><td><span class="label">Program</span>{{ $booking->program?->name }}<br>{{ $booking->program?->service?->name }}</td></tr><tr><td><span class="label">Departure</span>{{ $booking->starts_at->format('D, M d Y h:i A') }}</td><td><span class="label">Return</span>{{ $booking->ends_at->format('D, M d Y h:i A') }}</td><td><span class="label">Group total</span>{{ $booking->student_count }} students + {{ $booking->chaperone_count }} chaperones</td></tr><tr><td colspan="3"><span class="label">Pickup / itinerary stops</span>{{ $booking->pickup_location }}@if(count($booking->stops_snapshot ?? []))<br>{{ implode(' | ', $booking->stops_snapshot) }}@endif</td></tr></table>
<div class="section">Vehicle and passenger allocation</div><table class="fleet"><thead><tr><th>#</th><th>Vehicle</th><th>Driver</th><th>Capacity</th><th>Assigned passengers</th><th>Load status</th></tr></thead><tbody>@foreach($booking->vehicles as $index => $vehicle)<tr><td>{{ $index+1 }}</td><td>{{ $vehicle->bus?->plate_number }} {{ $vehicle->bus ? '- '.$vehicle->bus->model : '' }}</td><td>{{ $vehicle->driver ? trim($vehicle->driver->first_name.' '.$vehicle->driver->last_name) : 'Unassigned' }}</td><td>{{ $vehicle->capacity_snapshot }}</td><td>{{ $vehicle->planned_passengers }}</td><td>{{ $vehicle->planned_passengers <= $vehicle->capacity_snapshot ? 'Within capacity' : 'Review required' }}</td></tr>@endforeach</tbody></table>
<div class="section">Operations notes</div><div>{{ $booking->operations_notes ?: 'No special operations notes recorded.' }}</div><table class="signatures"><tr><td><div class="line">Prepared by</div></td><td><div class="line">Lead teacher / coordinator</div></td><td><div class="line">Operations approval</div></td></tr></table><div class="footer">Confidential operational document | Generated {{ $generatedAt->format('M d, Y h:i A') }} | Student information must be handled confidentially.</div></body></html>
